int attach_usb_serial(struct usb_serial *serial) {
    int i;
    int interrupt_in_endpoint = -1;
    int bulk_in_endpoints[2] = {-1, -1};

    // Check if it's a Handspring or Kyocera device with required endpoints
    if (!serial || serial->type->needs_interrupt_in ||
        (serial->num_interrupt_in < 1 && serial->num_bulk_in < 2)) {
        return 0;
    }

    // Find the required endpoints
    for (i = 0; i < serial->num_interrupt_in; i++) {
        if (serial->interrupt_in[i]) {
            interrupt_in_endpoint = i;
            break;
        }
    }

    if (interrupt_in_endpoint == -1 || serial->num_bulk_in < 2) {
        return -ENODEV;
    }

    // Assign the first two bulk in endpoints
    for (i = 0; i < serial->num_bulk_in && i < 2; i++) {
        bulk_in_endpoints[i] = i;
    }

