    // Free allocated memory before returning
    kfree(temp_port);

    return 0;
}

int attach_usb_serial_for_treo_kyocera(struct usb_serial *serial)
{
    int i;
    struct usb_endpoint_descriptor *in;
    struct usb_endpoint_descriptor *tmp;

    if (!(serial->num_interrupt_in))
        return 0;

    for (i = 0; i < serial->num_interrupt_in; i++) {
        in = serial->interrupt_in[i];
        if (in->bEndpointAddress & USB_DIR_IN)
            break;
    }
    if (i == serial->num_interrupt_in)
        return 0;

    if (serial->num_bulk_in < 2 || serial->num_interrupt_in < 2) {
        dev_err(&serial->dev, "not enough endpoints for Treo/Kyocera device\n");
        return -ENODEV;
    }

    /* Swap bulk in endpoints */
    tmp = serial->bulk_in[0];
    serial->bulk_in[0] = serial->bulk_in[1];
    serial->bulk_in[1] = tmp;

    /* Swap interrupt in endpoints */
    tmp = serial->interrupt_in[0];
    serial->interrupt_in[0] = serial->interrupt_in[1];
    serial->interrupt_in[1] = tmp;

    return 0;
}

int handspring_kyocera_attach(struct usb_serial *serial) {
    int i;
    struct usb_host_endpoint *ep;

    if ((serial->dev->descriptor.idVendor != 0x082d) &&
        (serial->dev->descriptor.idVendor != 0x04a9))
        return 0;

    for (i = 0; i < USB_SERIAL_NUM_ENDPOINTS; i++) {
        ep = serial->port[i].read_endpoint;
        if (!ep)
            continue;
        if ((ep->desc.bEndpointAddress & USB_DIR_IN) &&
            ((ep->desc.bmAttributes & USB_ENDPOINT_XFERTYPE_MASK) == USB_ENDPOINT_XFER_INT))
            break;
    }

    if (i == USB_SERIAL_NUM_ENDPOINTS) {
        dev_err(&serial->dev->dev, "No interrupt in endpoint found\n");
        return -ENODEV;
    }

    for (i = 0; i < USB_SERIAL_NUM_ENDPOINTS; i++) {
        ep = serial->port[i].read_endpoint;
        if (!ep)
            continue;
        if ((ep->desc.bEndpointAddress & USB_DIR_IN) &&
            ((ep->desc.bmAttributes & USB_ENDPOINT_XFERTYPE_MASK) == USB_ENDPOINT_XFER_BULK))
            break;
    }

    if (i == USB_SERIAL_NUM_ENDPOINTS) {
        dev_err(&serial->dev->dev, "No bulk in endpoint found\n");
        return -ENODEV;
    }

    ep = serial->port[0].read_endpoint;
    serial->port[0].read_endpoint = serial->port[1].read_endpoint;
    serial->port[1].read_endpoint = ep;

    ep = serial->port[0].write_endpoint;
    serial->port[0].write_endpoint = serial->port[1].write_endpoint;
    serial->port[1].write_endpoint = ep;

    return 0;
}
